package com.bank.compare;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// FLINK: true record-at-a-time. Each event processed immediately with rich per-key state.
class FlinkEngine {
    private static final Logger log = Logger.getLogger(FlinkEngine.class.getName());

    private final long perEventLatencyMs;
    // Rich keyed state: running count + sum per account (ValueState/MapState equivalent).
    private final Map<String, long[]> keyedState = new HashMap<>(); // [count, sum]
    private final List<Long> latencies = new ArrayList<>();

    FlinkEngine(long perEventLatencyMs) { this.perEventLatencyMs = perEventLatencyMs; }

    void onEvent(Event e) {
        long emitMs = e.arrivalMs + perEventLatencyMs;       // emitted almost immediately
        long latency = emitMs - e.arrivalMs;
        latencies.add(latency);
        long[] st = keyedState.computeIfAbsent(e.accountId, k -> new long[2]);
        st[0]++; st[1] += e.amount;                          // update rich per-key state now
        log.info(() -> "Flink emitted for " + e.accountId + " at +" + latency
                + "ms (state: count=" + st[0] + ", sum=Rs." + st[1] + ")");
    }

    double avgLatency() { return latencies.stream().mapToLong(Long::longValue).average().orElse(0); }
}
