package com.bank.compare;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// SPARK: micro-batch. Events buffered until the trigger interval, then processed together.
class SparkStructuredStreaming {
    private static final Logger log = Logger.getLogger(SparkStructuredStreaming.class.getName());

    private final long triggerIntervalMs;
    private final List<Long> latencies = new ArrayList<>();

    SparkStructuredStreaming(long triggerIntervalMs) { this.triggerIntervalMs = triggerIntervalMs; }

    // Process a whole list of events as micro-batches on fixed intervals.
    void processStream(List<Event> events) {
        long batchStart = 0;
        List<Event> batch = new ArrayList<>();
        for (Event e : events) {
            if (e.arrivalMs >= batchStart + triggerIntervalMs && !batch.isEmpty()) {
                emitBatch(batch, batchStart + triggerIntervalMs);
                batch = new ArrayList<>();
                batchStart = (e.arrivalMs / triggerIntervalMs) * triggerIntervalMs;
            }
            batch.add(e);
        }
        if (!batch.isEmpty()) emitBatch(batch, batchStart + triggerIntervalMs);
    }

    private void emitBatch(List<Event> batch, long emitMs) {
        long sum = batch.stream().mapToLong(e -> e.amount).sum();
        for (Event e : batch) latencies.add(Math.max(0, emitMs - e.arrivalMs)); // waited for batch
        log.info(() -> "Spark micro-batch of " + batch.size() + " events emitted at " + emitMs
                + "ms (batch sum=Rs." + sum + ") — same DataFrame/SQL engine as batch");
    }

    double avgLatency() { return latencies.stream().mapToLong(Long::longValue).average().orElse(0); }
}
