package com.bank.compare;

import java.util.List;
import java.util.logging.Logger;

// Runs the same stream through both engines and contrasts latency + model.
class LatencyComparer {
    private static final Logger log = Logger.getLogger(LatencyComparer.class.getName());

    void compare(List<Event> events, FlinkEngine flink, SparkStructuredStreaming spark) {
        log.info("--- Flink (true record-at-a-time) ---");
        for (Event e : events) flink.onEvent(e);

        log.info("--- Spark Structured Streaming (micro-batch) ---");
        spark.processStream(events);

        log.info(() -> "Avg latency — Flink=" + flink.avgLatency() + "ms, Spark=" + spark.avgLatency() + "ms");
        log.info("State model — Flink: rich keyed state + timers (per event); "
                + "Spark: windowed/arbitrary stateful on micro-batches, unified with batch/SQL/ML");
    }
}
