package com.bank.compare;

import java.util.List;
import java.util.logging.Logger;

public class CompareDemo {
    private static final Logger log = Logger.getLogger(CompareDemo.class.getName());

    public static void main(String[] args) {
        // Transactions arriving over ~1.3 seconds.
        List<Event> events = List.of(
            new Event("SAV2001", 50000, 100),
            new Event("CUR3001", 80000, 300),
            new Event("SAV2001", 30000, 700),
            new Event("CUR3001", 500000, 1100),
            new Event("SAV2001", 20000, 1250));

        FlinkEngine flink = new FlinkEngine(5);                 // ~5ms per event
        SparkStructuredStreaming spark = new SparkStructuredStreaming(1000); // 1s batches

        new LatencyComparer().compare(events, flink, spark);

        log.info("Guidance: Flink for sub-second, heavily-stateful fraud reaction; "
                + "Spark Structured Streaming for streaming alongside batch/analytics/ML in one ecosystem");
    }
}
